def query_attributes(self):
    """Return temperature states."""
    response = {}
    unit = self.hass.config.units.temperature_unit
    current_temp = self.state.state
    if current_temp not in (STATE_UNKNOWN, STATE_UNAVAILABLE):
        temp = round(
            TemperatureConverter.convert(float(current_temp), unit, TEMP_CELSIUS), 1
        )
        response["temperatureSetpointCelsius"] = temp
        response["temperatureAmbientCelsius"] = temp

    return response

def query_attributes(self):
    """Return temperature point and modes query attributes."""
    response = {}
    attrs = self.state.attributes
    unit = self.hass.config.units.temperature_unit

    operation = self.state.state
    preset = attrs.get(climate.ATTR_PRESET_MODE)
    supported = attrs.get(ATTR_SUPPORTED_FEATURES, 0)

    if preset in self.preset_to_google:
        response["thermostatMode"] = self.preset_to_google[preset]
    else:
        response["thermostatMode"] = self.hvac_to_google.get(operation, "none")

    current_temp = attrs.get(climate.ATTR_CURRENT_TEMPERATURE)
    if current_temp is not None:
        response["thermostatTemperatureAmbient"] = round(
            TemperatureConverter.convert(current_temp, unit, TEMP_CELSIUS), 1
        )

    current_humidity = attrs.get(climate.ATTR_CURRENT_HUMIDITY)
    if current_humidity is not None:
        response["thermostatHumidityAmbient"] = current_humidity

    if operation in (climate.HVACMode.AUTO, climate.HVACMode.HEAT_COOL):
        if supported & climate.SUPPORT_TARGET_TEMPERATURE_RANGE:
            response["thermostatTemperatureSetpointHigh"] = round(
                TemperatureConverter.convert(
                    attrs[climate.ATTR_TARGET_TEMP_HIGH], unit, TEMP_CELSIUS
                ),
                1,
            )
            response["thermostatTemperatureSetpointLow"] = round(
                TemperatureConverter.convert(
                    attrs[climate.ATTR_TARGET_TEMP_LOW], unit, TEMP_CELSIUS
                ),
                1,
            )
        else:
            if (target_temp := attrs.get(ATTR_TEMPERATURE)) is not None:
                target_temp = round(
                    TemperatureConverter.convert(target_temp, unit, TEMP_CELSIUS), 1
                )
                response["thermostatTemperatureSetpointHigh"] = target_temp
                response["thermostatTemperatureSetpointLow"] = target_temp
    else:
        if (target_temp := attrs.get(ATTR_TEMPERATURE)) is not None:
            response["thermostatTemperatureSetpoint"] = round(
                TemperatureConverter.convert(target_temp, unit, TEMP_CELSIUS), 1
            )

    return response

async def execute(self, command, data, params, challenge):
    """Execute a temperature point or mode command."""
    # All sent in temperatures are always in Celsius
    unit = self.hass.config.units.temperature_unit
    min_temp = self.state.attributes[climate.ATTR_MIN_TEMP]
    max_temp = self.state.attributes[climate.ATTR_MAX_TEMP]

    if command == COMMAND_THERMOSTAT_TEMPERATURE_SETPOINT:
        temp = TemperatureConverter.convert(
            params["thermostatTemperatureSetpoint"], TEMP_CELSIUS, unit
        )
        if unit == TEMP_FAHRENHEIT:
            temp = round(temp)

        if temp < min_temp or temp > max_temp:
            raise SmartHomeError(
                ERR_VALUE_OUT_OF_RANGE,
                f"Temperature should be between {min_temp} and {max_temp}",
            )

        await self.hass.services.async_call(
            climate.DOMAIN,
            climate.SERVICE_SET_TEMPERATURE,
            {ATTR_ENTITY_ID: self.state.entity_id, ATTR_TEMPERATURE: temp},
            blocking=not self.config.should_report_state,
            context=data.context,
        )

    elif command == COMMAND_THERMOSTAT_TEMPERATURE_SET_RANGE:
        temp_high = TemperatureConverter.convert(
            params["thermostatTemperatureSetpointHigh"], TEMP_CELSIUS, unit
        )
        if unit == TEMP_FAHRENHEIT:
            temp_high = round(temp_high)

        if temp_high < min_temp or temp_high > max_temp:
            raise SmartHomeError(
                ERR_VALUE_OUT_OF_RANGE,
                (
                    f"Upper bound for temperature range should be between "
                    f"{min_temp} and {max_temp}"
                ),
            )

        temp_low = TemperatureConverter.convert(
            params["thermostatTemperatureSetpointLow"], TEMP_CELSIUS, unit
        )
        if unit == TEMP_FAHRENHEIT:
            temp_low = round(temp_low)

        if temp_low < min_temp or temp_low > max_temp:
            raise SmartHomeError(
                ERR_VALUE_OUT_OF_RANGE,
                (
                    f"Lower bound for temperature range should be between "
                    f"{min_temp} and {max_temp}"
                ),
            )

        supported = self.state.attributes.get(ATTR_SUPPORTED_FEATURES)
        svc_data = {ATTR_ENTITY_ID: self.state.entity_id}

        if supported & climate.SUPPORT_TARGET_TEMPERATURE_RANGE:
            svc_data[climate.ATTR_TARGET_TEMP_HIGH] = temp_high
            svc_data[climate.ATTR_TARGET_TEMP_LOW] = temp_low
        else:
            svc_data[ATTR_TEMPERATURE] = (temp_high + temp_low) / 2

        await self.hass.services.async_call(
            climate.DOMAIN,
            climate.SERVICE_SET_TEMPERATURE,
            svc_data,
            blocking=not self.config.should_report_state,
            context=data.context,
        )

    elif command == COMMAND_THERMOSTAT_SET_MODE:
        target_mode = params["thermostatMode"]
        supported = self.state.attributes.get(ATTR_SUPPORTED_FEATURES)

        if target_mode == "on":
            await self.hass.services.async_call(
                climate.DOMAIN,
                SERVICE_TURN_ON,
                {ATTR_ENTITY_ID: self.state.entity_id},
                blocking=not self.config.should_report_state,
                context=data.context,
            )
            return

        if target_mode == "off":
            await self.hass.services.async_call(
                climate.DOMAIN,
                SERVICE_TURN_OFF,
                {ATTR_ENTITY_ID: self.state.entity_id},
                blocking=not self.config.should_report_state,
                context=data.context,
            )
            return

        if target_mode in self.google_to_preset:
            await self.hass.services.async_call(
                climate.DOMAIN,
                climate.SERVICE_SET_PRESET_MODE,
                {
                    climate.ATTR_PRESET_MODE: self.google_to_preset[target_mode],
                    ATTR_ENTITY_ID: self.state.entity_id,
                },
                blocking=not self.config.should_report_state,
                context=data.context,
            )
            return

        await self.hass.services.async_call(
            climate.DOMAIN,
            climate.SERVICE_SET_HVAC_MODE,
            {
                ATTR_ENTITY_ID: self.state.entity_id,
                climate.ATTR_HVAC_MODE: self.google_to_hvac[target_mode],
            },
            blocking=not self.config.should_report_state,
            context=data.context,
        )

def temperature_to_homekit(temperature: float | int, unit: str) -> float:
    """Convert temperature to Celsius for HomeKit."""
    return round(TemperatureConverter.convert(temperature, unit, TEMP_CELSIUS), 1)

def temperature_to_states(temperature: float | int, unit: str) -> float:
    """Convert temperature back from Celsius to Home Assistant unit."""
    return round(TemperatureConverter.convert(temperature, TEMP_CELSIUS, unit) * 2) / 2

@staticmethod
def _update_temp_sensor(state):
    """Parse temperature sensor value."""
    _LOGGER.debug("Updating temp sensor with value %s", state.state)

    # Return an error if the sensor change its state to Unknown.
    if state.state == STATE_UNKNOWN:
        _LOGGER.error(
            "Unable to parse temperature sensor %s with state: %s",
            state.entity_id,
            state.state,
        )
        return None

    unit = state.attributes.get(ATTR_UNIT_OF_MEASUREMENT)

    if (temp := util.convert(state.state, float)) is None:
        _LOGGER.error(
            "Unable to parse temperature sensor %s with state: %s",
            state.entity_id,
            state.state,
        )
        return None

    # convert to celsius if necessary
    if unit == TEMP_FAHRENHEIT:
        return TemperatureConverter.convert(temp, TEMP_FAHRENHEIT, TEMP_CELSIUS)
    if unit == TEMP_CELSIUS:
        return temp
    _LOGGER.error(
        "Temp sensor %s has unsupported unit: %s (allowed: %s, %s)",
        state.entity_id,
        unit,
        TEMP_CELSIUS,
        TEMP_FAHRENHEIT,
    )

    return None

@property
def extra_state_attributes(self):
    """Return the state attributes."""
    if self._is_metric:
        return {
            ATTR_DEWPOINT: round(self._dewpoint, 2),
            ATTR_CRITICAL_TEMP: round(self._crit_temp, 2),
        }

    dewpoint = (
        TemperatureConverter.convert(self._dewpoint, TEMP_CELSIUS, TEMP_FAHRENHEIT)
        if self._dewpoint is not None
        else None
    )

    crit_temp = (
        TemperatureConverter.convert(self._crit_temp, TEMP_CELSIUS, TEMP_FAHRENHEIT)
        if self._crit_temp is not None
        else None
    )

    return {
        ATTR_DEWPOINT: round(dewpoint, 2),
        ATTR_CRITICAL_TEMP: round(crit_temp, 2),
    }

@property
def forecast(self):
    """Return forecast."""
    if self._forecast is None:
        return None
    forecast = []
    for forecast_entry in self._forecast:
        data = {
            ATTR_FORECAST_DETAILED_DESCRIPTION: forecast_entry.get(
                "detailedForecast"
            ),
            ATTR_FORECAST_TIME: forecast_entry.get("startTime"),
        }

        if (temp := forecast_entry.get("temperature")) is not None:
            data[ATTR_FORECAST_NATIVE_TEMP] = TemperatureConverter.convert(
                temp, TEMP_FAHRENHEIT, TEMP_CELSIUS
            )
        else:
            data[ATTR_FORECAST_NATIVE_TEMP] = None

        if self.mode == DAYNIGHT:
            data[ATTR_FORECAST_DAYTIME] = forecast_entry.get("isDaytime")
        time = forecast_entry.get("iconTime")
        weather = forecast_entry.get("iconWeather")
        if time and weather:
            cond, precip = convert_condition(time, weather)
        else:
            cond, precip = None, None
        data[ATTR_FORECAST_CONDITION] = cond
        data[ATTR_FORECAST_PRECIPITATION_PROBABILITY] = precip

        data[ATTR_FORECAST_WIND_BEARING] = forecast_entry.get("windBearing")
        wind_speed = forecast_entry.get("windSpeedAvg")
        if wind_speed is not None:
            data[ATTR_FORECAST_NATIVE_WIND_SPEED] = SpeedConverter.convert(
                wind_speed, SPEED_MILES_PER_HOUR, SPEED_KILOMETERS_PER_HOUR
            )
        else:
            data[ATTR_FORECAST_NATIVE_WIND_SPEED] = None
        forecast.append(data)
    return forecast

@staticmethod
